async function withDeadline<T>(op: (signal: AbortSignal) => Promise<T>, ms: number): Promise<T> {
  const signal = AbortSignal.timeout(ms);   // lib.dom / @types/node (Node 17.3+)
  try {
    return await op(signal);
  } catch (err) {
    if (err instanceof DOMException && err.name === 'TimeoutError') throw new DependencyTimeout(ms);
    throw err;
  }
}

